import{_ as a}from"./chunks/sh2.C2f6EkLz.js";import{_ as o,c as t,o as n,ae as i}from"./chunks/framework.BrQRMotl.js";const v=JSON.parse('{"title":"Advanced Mode","description":"","frontmatter":{},"headers":[],"relativePath":"manual/advanced_mode.md","filePath":"manual/advanced_mode.md"}'),l={name:"manual/advanced_mode.md"};function s(d,e,r,c,u,h){return n(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="advanced-mode" tabindex="-1">Advanced Mode <a class="header-anchor" href="#advanced-mode" aria-label="Permalink to &quot;Advanced Mode&quot;">​</a></h1><p>In the Extended Note Block interface, you can find the <strong>&quot;Advanced Mode&quot;</strong> button. Entering this mode unlocks more powerful audio rendering controls.</p><p><img src="'+a+'" alt="Advanced Mode"></p><h2 id="visual-envelopes" tabindex="-1">Visual Envelopes <a class="header-anchor" href="#visual-envelopes" aria-label="Permalink to &quot;Visual Envelopes&quot;">​</a></h2><p>Advanced Mode provides two core visual editors:</p><h3 id="_1-volume-envelope" tabindex="-1">1. Volume Envelope <a class="header-anchor" href="#_1-volume-envelope" aria-label="Permalink to &quot;1. Volume Envelope&quot;">​</a></h3><ul><li>Controls volume changes during playback.</li><li><strong>Edit</strong>: Click and drag points on the curve to change its shape.</li><li><strong>Function</strong>: Achieve complex fade-ins, fade-outs, vibrato, or gradual decay effects.</li><li><strong>Note</strong>: When fade-in/out in Normal Mode and the Volume Envelope in Advanced Mode exist simultaneously, the Volume Envelope in Advanced Mode overrides the Normal Mode settings.</li></ul><h3 id="_2-pitch-envelope" tabindex="-1">2. Pitch Envelope <a class="header-anchor" href="#_2-pitch-envelope" aria-label="Permalink to &quot;2. Pitch Envelope&quot;">​</a></h3><ul><li>Controls pitch shifts during playback.</li><li><strong>Edit</strong>: Same as above.</li><li><strong>Function</strong>: Achieve portamento, pitch vibrato, or special sound effects.</li><li><strong>Note</strong>: When pitch in Normal Mode and the Pitch Envelope in Advanced Mode exist simultaneously, the Pitch Envelope in Advanced Mode overrides the Normal Mode pitch.</li></ul><hr><h2 id="dynamic-sound-source-movement" tabindex="-1">Dynamic Sound Source Movement <a class="header-anchor" href="#dynamic-sound-source-movement" aria-label="Permalink to &quot;Dynamic Sound Source Movement&quot;">​</a></h2><p>This is a unique feature of the Extended Note Block, allowing sound to &quot;wander&quot; in space over time. By entering <strong>mathematical expressions</strong>, you can define the relative offset of the sound source on the X, Y, and Z axes.</p><h3 id="variables" tabindex="-1">Variables: <a class="header-anchor" href="#variables" aria-label="Permalink to &quot;Variables:&quot;">​</a></h3><ul><li><code>t</code>: The percentage of the current playback progress (0.0 to 1.0).</li><li><code>d</code>: The current playback time in Ticks (1 Tick = 0.05 seconds).</li><li><code>pi</code>: The constant <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>π</mi></mrow><annotation encoding="application/x-tex">\\pi</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.43056em;"></span><span class="strut bottom" style="height:0.43056em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.03588em;">π</span></span></span></span> (approximately 3.14159).</li></ul><h3 id="common-functions" tabindex="-1">Common Functions: <a class="header-anchor" href="#common-functions" aria-label="Permalink to &quot;Common Functions:&quot;">​</a></h3><p>Supports standard mathematical functions such as <code>sin</code>, <code>cos</code>, <code>tan</code>, <code>abs</code>, <code>sqrt</code>, <code>log</code>, <code>exp</code>, etc.</p><h3 id="example-usage" tabindex="-1">Example Usage: <a class="header-anchor" href="#example-usage" aria-label="Permalink to &quot;Example Usage:&quot;">​</a></h3><ul><li><strong>Circular Motion</strong>: <ul><li>X Axis: <code>5 * sin(2 * pi * t)</code></li><li>Z Axis: <code>5 * cos(2 * pi * t)</code></li><li><em>Effect: The sound source will rotate around the Note Block with a radius of 5 blocks.</em></li></ul></li><li><strong>Vertical Rise</strong>: <ul><li>Y Axis: <code>t * 10</code></li><li><em>Effect: The sound will rise 10 blocks gradually during playback.</em></li></ul></li><li><strong>Sine Wave Oscillation</strong>: <ul><li>Y Axis: <code>sin(d * 0.5)</code></li><li><em>Effect: The sound will oscillate up and down.</em></li></ul></li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>If a red warning appears in the expression input box, it indicates a syntax error.</li></ul>',20)])])}const g=o(l,[["render",s]]);export{v as __pageData,g as default};
